  "a_sentences": [
    {
      "a_text": "Die Versicherte bestreitet die auf Art. 25a Abs. 5 KVG gestützte kantonale Restfinanzierung von Grundpflegeleistungen, die sie durch angestellte Angehörige erbringen lässt, und rügt deren Höhe.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Wirtschaftlichkeit von Leistungen nach Art. 32 Abs. 1 KVG begrenzt den zu deckenden Pflegebedarf und verlangt eine kostengünstige Bedarfsdeckung.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Der Leistungserbringer hat keinen Anspruch auf Entschädigung seiner Vollkosten; das Wirtschaftlichkeitsgebot schränkt den Umfang der versicherten Leistungen ein.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Bei der abstrakten Normenkontrolle prüft das Bundesgericht die Bundesrechtskonformität des kantonalen Erlasses frei, auferlegt sich jedoch eine gewisse Zurückhaltung gegenüber kantonaler Gestaltungsfreiheit und den Grundsätzen des Föderalismus.",
      "b_propositions": ["P5", "P6"]
    },
    {
      "a_text": "Der aus der Kombination verschiedener Methoden ermittelte Restfinanzierungsbeitrag von Fr. 8.80/h erweist sich als grundsätzlich bundesrechtskonform.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Art. 31 Abs. 3a PBV/GL, der den kantonalen Restfinanzierungsbeitrag für Grundpflege durch angestellte Angehörige auf Fr. 8.80/h festlegt, verletzt kein Bundesrecht.",
      "b_propositions": ["P8"]
    }
  ]
}
